#!/usr/bin/env python3
"""Regenerate INDEX.md and by-industry/*.md from program frontmatter. Run from materials/subsidies/."""
import glob, os, yaml

TODAY = "2026-06-04"
PROG_DIR = "programs"

IND_FILES = {
    "製造業": "manufacturing.md",
    "科技業": "technology.md",
    "服務業": "services.md",
    "零售業": "retail.md",
    "農業": "agriculture.md",
    "醫療業": "healthcare.md",
    "設計業": "design.md",
    "全產業": "all-industries.md",
}

def extract_fm(txt):
    lines = txt.splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            end = i
            break
    if end is None:
        return None
    return "\n".join(lines[1:end])

def load():
    progs = []
    for path in glob.glob(os.path.join(PROG_DIR, "*.md")):
        with open(path, encoding="utf-8") as f:
            txt = f.read()
        fm = extract_fm(txt)
        if fm is None:
            print("  WARN no frontmatter:", path)
            continue
        try:
            meta = yaml.safe_load(fm) or {}
        except Exception as e:
            print("  WARN yaml error:", path, e)
            continue
        if meta.get("status") != "active":
            continue
        meta["_file"] = os.path.basename(path)
        progs.append(meta)
    return progs

def dkey(p):
    d = (p.get("deadline") or "").strip()
    return (d == "", d)

def fmt_deadline(p):
    d = (p.get("deadline") or "").strip()
    if not d:
        return "長期/隨到隨審"
    flag = " ⚠️" if d <= "2026-06-30" else ""
    return d + flag

def tags(p):
    return "、".join(p.get("industry_tags") or [])

def link(p):
    return f"[詳情](programs/{p['_file']})"

def name(p):
    return (p.get("name") or p["_file"]).strip()

def main():
    progs = sorted(load(), key=dkey)
    active = len(progs)
    expiring = [p for p in progs if (p.get("deadline") or "") and p["deadline"] <= "2026-06-30"]

    lines = []
    lines.append("# 政府補助計畫索引 (INDEX)")
    lines.append("")
    lines.append(f"> 自動產生於 {TODAY} by `subsidy-scraper` skill。資料來源：grants.nat.gov.tw / SBIR / SIIR 及各部會公告。")
    lines.append(f"> **現行有效計畫：{active} 件**　|　封存（已截止）：見 `programs/archived/`")
    lines.append("")
    lines.append(f"⚠️ = 截止日在 2026-06-30（含）前，請優先處理（共 {len(expiring)} 件）。")
    lines.append("")
    lines.append("| 補助名稱 | 主辦機關 | 截止日期 | 適用產業 | 詳情 |")
    lines.append("|----------|----------|----------|----------|------|")
    for p in progs:
        lines.append(f"| {name(p)} | {(p.get('agency') or '').strip()} | {fmt_deadline(p)} | {tags(p)} | {link(p)} |")
    lines.append("")
    lines.append("## 依產業分類")
    lines.append("")
    for ind, fn in IND_FILES.items():
        cnt = sum(1 for p in progs if ind in (p.get("industry_tags") or []))
        lines.append(f"- [{ind}](by-industry/{fn}) — {cnt} 件")
    lines.append("")
    with open("INDEX.md", "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")

    os.makedirs("by-industry", exist_ok=True)
    for ind, fn in IND_FILES.items():
        sub = sorted([p for p in progs if ind in (p.get("industry_tags") or [])], key=dkey)
        out = []
        out.append(f"# {ind} — 適用補助計畫")
        out.append("")
        out.append(f"> 自動產生於 {TODAY}。共 {len(sub)} 件現行有效計畫。⚠️ = 6/30（含）前截止。")
        out.append("")
        out.append("| 補助名稱 | 主辦機關 | 截止日期 | 補助金額 | 詳情 |")
        out.append("|----------|----------|----------|----------|------|")
        for p in sub:
            fa = (p.get("funding_amount") or "").replace("\n", " ").strip()
            if len(fa) > 40:
                fa = fa[:38] + "…"
            out.append(f"| {name(p)} | {(p.get('agency') or '').strip()} | {fmt_deadline(p)} | {fa} | {link(p)} |")
        out.append("")
        with open(os.path.join("by-industry", fn), "w", encoding="utf-8") as f:
            f.write("\n".join(out) + "\n")

    print(f"active={active} expiring_by_0630={len(expiring)}")
    for ind, fn in IND_FILES.items():
        cnt = sum(1 for p in progs if ind in (p.get("industry_tags") or []))
        print(f"  {ind}: {cnt}")

if __name__ == "__main__":
    main()

